import {
  AddEquation,
  AdditiveBlending,
  BackSide,
  Color,
  CustomBlending,
  DataTexture,
  OneFactor,
  OneMinusSrcAlphaFactor,
  ShaderChunk,
  ShaderMaterial,
  Vector2,
  Vector3
} from 'three'
import { ringDustRaymarchFunctions, ringDustUniforms } from '@/core/materials/shaders/lib/chunks/RingDust'
import { sceneDepthFunctions, sceneDepthUniforms } from '@/core/materials/shaders/lib/chunks/SceneDepth'
import { createDustClumpGradientTexture, dustClumpNoiseFunctions } from './DustClumpNoise'
import type { Actor } from '@/core/models/Actor'
import { resolveLightTint } from '@/core/helpers/lightSource'

/**
 * RingDustRaymarchMaterial — аддитивное пылевое гало кольца (реймарч).
 *
 * Рендерится на ОХВАТЫВАЮЩЕЙ прокси-сфере (BackSide, radius ≥ outerRadius):
 * фрагмент задаёт ТОЛЬКО направление луча, интервалы интегрирования находятся
 * аналитически (внешний цилиндр минус дыра, обрезка по вертикальной оболочке
 * 12H). Сфера гарантирует полное покрытие пикселей кольца из любого ракурса —
 * тонкая шайба (v2.0) с ребра покрывала лишь узкую полосу и давала «брус» из
 * собственных граней; сфера этого артефакта лишена.
 *
 * Блендинг АДДИТИВНЫЙ (порядок прозрачных не важен, гало не даёт «бруса»),
 * depthWrite OFF и depthTest OFF: перекрытие считает сам марш.
 *
 * Перекрытие — по ГЛУБИНЕ СЦЕНЫ, а не аппаратным тестом. Один фрагмент прокси
 * несёт интеграл вдоль всего луча, и бинарный тест не умеет «пыль до камня
 * есть, за камнем нет»: с глубиной дальней стенки прокси гало целиком срезали
 * камни, плотные тексели кольца и планета; с глубиной точки входа в слой —
 * целиком пропускали вместе с пылью ЗА ними, и планета в дыре кольца с камнями
 * внутри слоя просвечивали. Поэтому материал рисуется пассом DepthVolumePass после
 * сцены и режет оба пыльных интервала по tScene из общего чанка SceneDepth
 * (копия depth-текстуры, декод лог-глубины three, перевод в параметр луча).
 * Луч, упёршийся в поверхность до входа в слой, схлопывается в пустой
 * интервал и уходит в discard.
 *
 * Марш идёт только внутри пыльных интервалов (не жжём шаги на пустоте):
 * фиксированный бюджет шагов, IGN-джиттер против бандинга, early-exit по
 * насыщению. Плотность аналитическая (~5 ALU) — 3D-текстура не нужна; марш
 * выбран как точка расширения под будущие «клочья» (см. спеку v2).
 *
 * Модель плотности — общая с материалами камней (чанк RingDust).
 *
 * CPU-зеркало цикла марша: tauMarch в tests/ringDust/tauMirror.ts —
 * менять строго синхронно.
 *
 * Клочья (DUST_CLUMPS) — низкочастотный шум плотности только в марше объёма.
 * Замкнутая форма тумана на камнях (ringDustTauRay) не видит ни клочьев, ни
 * фазы: у пояса туман камней — отдельный художественный туман по дистанции,
 * а не τ объёма, и согласованности между ними нет по замыслу; у колец клочья
 * не используются.
 *
 * Дуги (DUST_ARCS) — азимутальный профиль плотности пояса из 1D-текстуры
 * (см. DustRadialProfile.createDustAngularTexture): u = atan(p.z, p.x) / 2π,
 * тот же отсчёт угла, что у секторов стримера и точек дальнего слоя. Как и
 * клочья, дуги видит только марш объёма — туман камней (ringDustTauRay) их
 * не знает.
 *
 * Фазовый свет (DUST_PHASE_HG) — форвард-скаттеринг: дымка ярче, если луч
 * смотрит сквозь неё на звезду, и темнее, если от звезды. Фаза Хеньи-Гринштейна
 * взята БЕЗ множителя 1/(4π): среднее по сфере равно 1 по построению.
 * uDustPhaseStrength смешивает прежнюю дымку (ringDustHazeSun) с фазовой
 * моделью; средняя по сфере яркость обеих одна (константа RING_DUST_PHASE_BASE
 * = среднее прежней модели), меняется только распределение по направлению
 * луча. При дефолте uDustPhaseG = 0.55 отношение вперёд/назад к среднему
 * ≈ 7.65 / 0.19.
 *
 * Поглощение (extinction) — дымка не только добавляет свет, но и гасит то,
 * что за ней: звезду, её гало и фон (а через них — блик и блум hdr-пасса).
 * Блендинг переключается на премультиплированный over (One, OneMinusSrcAlpha):
 * цвет выдаётся уже умноженным на прежний вес alpha, так что добавленный свет
 * равен haze·litFrac·alpha — байт-в-байт тот же, что у аддитивной модели, — а
 * фон умножается на пропускание 1 − alphaExt, где alphaExt считается по
 * τ·uDustExtinction под тем же гейтом (угол, ближнее гашение). При
 * uDustExtinction = 0 результат равен аддитивному. Кольца опцию не ставят и
 * остаются аддитивными с прежним текстом программы.
 */
interface RingDustRaymarchOptions {
  /**
   * Светило в начале ring-local (пояс вокруг звезды): прямой лепесток дымки
   * считается по направлению на звезду из каждой точки марша, а не по
   * uDustLightDirRing. Кольца у планеты — false: текст программы прежний.
   */
  lightAtOrigin?: boolean
  /**
   * Низкочастотная модуляция плотности («клочья»): под дефайном, чтобы текст
   * программы колец оставался байт-в-байт прежним без флага.
   */
  clumps?: boolean
  /**
   * Фазовая функция Хеньи-Гринштейна («фазовый свет»): под дефайном, чтобы
   * текст программы без флага оставался байт-в-байт прежним.
   */
  phaseHG?: boolean
  /**
   * Азимутальный профиль плотности («дуги» пояса): под дефайном, чтобы текст
   * программы колец без флага оставался байт-в-байт прежним.
   */
  arcs?: boolean
  /**
   * Поглощение света за дымкой (пояс): блендинг over вместо аддитивного,
   * пропускание по uDustExtinction. Без флага текст программы и блендинг прежние.
   */
  extinction?: boolean
}

class RingDustRaymarchMaterial extends ShaderMaterial {
  private clumpGradients: DataTexture | undefined

  /**
   * `model` — актор кольца (тот же вход, что у камней; резолвер сам
   * поднимается к корню дерева); `undefined` — тинт выключен.
   */
  public constructor(model?: Actor, options: RingDustRaymarchOptions = {}) {
    const lightTint = model ? resolveLightTint(model) : { active: false, color: new Color(1, 1, 1) }

    // Клочья вставляются строковой композицией (не голым #ifdef в базовом
    // тексте): без options.clumps текст фрагментного шейдера остаётся
    // байт-в-байт прежним — кольца программу не меняют.
    const clumpDeclChunk = options.clumps
      ? `
        uniform float uDustClumpStrength;
        uniform float uDustClumpScale;
        ${dustClumpNoiseFunctions}`
      : ''
    const clumpContribChunk = options.clumps
      ? `
            #ifdef DUST_CLUMPS
              // Шаг марша крупнее половины клочка — клочья не сэмплируются и
              // вырождались бы в пиксельную крупу; гасим их силу до ровной
              // дымки (среднее шума единица) и не считаем шум вовсе. Вдоль
              // ленты шаг в единицы а.е., сверху — сотые доли: клочья видны там,
              // где их можно разрешить
              float clumpGain = uDustClumpStrength * clamp(uDustClumpScale / (2.0 * dt), 0.0, 1.0);
              if (clumpGain > 0.001) {
                // p — float32 ring-local до ~4e6 units; при масштабе клочьев
                // в десятки тысяч units аргумент шума порядка сотни. Масштабы
                // ниже ~100 units начнут алиасить
                vec3 clumpP = p / uDustClumpScale;
                float clumpNoise = dustClumpNoise(clumpP) + 0.5 * dustClumpNoise(clumpP * 2.0);
                float n = clumpNoise * 0.5 + 0.5;
                contrib *= mix(1.0 - clumpGain, 1.0 + clumpGain, n);
              }
            #endif`
      : ''

    // Clumpy system belts normally have neither shadow. Guard both calls before
    // entering their helpers; even disabled uniform branches cost GPU time in
    // this loop. Keep live uniform switching and the plain ring program intact.
    const shadowContribChunk = options.clumps
      ? `if (uDustPlanetRadius <= 0.0 && uRingBandEnabled < 0.5) {
              litTau += contrib;
            } else {
              litTau += contrib * ringDustPlanetShadow(p) * ringLayerShadow(p);
            }`
      : 'litTau += contrib * ringDustPlanetShadow(p) * ringLayerShadow(p);'

    // Дуги вставляются тем же приёмом: без options.arcs текст фрагментного
    // шейдера остаётся байт-в-байт прежним.
    const arcsDeclChunk = options.arcs
      ? `
        uniform sampler2D uDustAngularMap;
        uniform float uDustAngularMapScale;`
      : ''
    // Сразу после клочьев, до фазы и накопления tau/litTau: contrib несёт дуги
    // во все взвешенные суммы. u = θ/2π по atan(z, x) — бин i текстуры отвечает
    // углу 2π·i/bins, как у AngularDensityProfile; отрицательный u замыкает
    // оборот через wrap Repeat (см. createDustAngularTexture)
    const arcsContribChunk = options.arcs
      ? `
            #ifdef DUST_ARCS
              contrib *= texture2D(uDustAngularMap, vec2(atan(p.z, p.x) / PI2, 0.5)).r * uDustAngularMapScale;
            #endif`
      : ''

    // Фазовый свет вставляется тем же приёмом: без options.phaseHG текст
    // фрагментного шейдера остаётся байт-в-байт прежним.
    const phaseDeclChunk = options.phaseHG
      ? `
        uniform float uDustPhaseG;
        uniform float uDustPhaseStrength;
        uniform vec3 uDustColorForward;

        // HG без 1/(4π): среднее по сфере ровно 1, средняя яркость дымки не меняется
        float ringDustPhaseHG(float cosTheta) {
          float g = uDustPhaseG;
          float g2 = g * g;
          return (1.0 - g2) / pow(max(1.0 + g2 - 2.0 * g * cosTheta, 1e-4), 1.5);
        }`
      : ''
    const phaseTauDeclChunk = options.phaseHG
      ? `
          #ifdef DUST_PHASE_HG
            float phaseTau = 0.0; // τ, взвешенный фазой HG (среднее по сфере = 1 по построению)
          #endif`
      : ''
    // Вычисляется рядом с клочьями (contrib уже несёт их множитель) и до
    // tau/litTau — направление на звезду своё в каждой точке марша при
    // DUST_LIGHT_AT_ORIGIN, тот же смысл что toStar ниже по коду (не тот же
    // токен: та переменная объявлена позже своего ifdef-блока)
    const phaseContribChunk = options.phaseHG
      ? `
            #ifdef DUST_PHASE_HG
              #ifdef DUST_LIGHT_AT_ORIGIN
                float cosTheta = dot(rayDir, -p / max(length(p), 1e-6));
              #else
                float cosTheta = dot(rayDir, uDustLightDirRing);
              #endif
              phaseTau += contrib * ringDustPhaseHG(cosTheta);
            #endif`
      : ''
    // Подмешивает фазовую модель к haze из ветки DUST_LIGHT_AT_ORIGIN/else по
    // uDustPhaseStrength: 0 — прежняя дымка, 1 — тон к uDustColorForward,
    // яркость по среднему HG вдоль луча. Средняя по сфере яркость обеих
    // моделей одна (RING_DUST_PHASE_BASE), сила меняет только распределение
    const phaseHazeOverrideChunk = options.phaseHG
      ? `
          #ifdef DUST_PHASE_HG
            // Среднее по сфере прежней модели 0.75 + 0.45·⟨sun⟩, ⟨sun⟩ = ⟨max(cosθ,0)^4⟩ = 0.1
            const float RING_DUST_PHASE_BASE = 0.795;
            // Среднее HG по лучу: 1 нейтрально, >1 форвард (к звезде), <1 назад
            float phaseMean = tau > 0.0 ? phaseTau / tau : 1.0;
            float forward = clamp((phaseMean - 1.0) / 3.0, 0.0, 1.0);
            vec3 phaseHaze = mix(uDustColor, uDustColorForward, forward) * (phaseMean * RING_DUST_PHASE_BASE);
            #ifdef USE_LIGHT_TINT
              phaseHaze *= uLightColor;
            #endif
            haze = mix(haze, phaseHaze, uDustPhaseStrength);
          #endif`
      : ''

    // Поглощение — тем же приёмом: без options.extinction выход и объявления
    // остаются байт-в-байт прежними (аддитивный блендинг, alpha как вес вклада)
    const extinctionDeclChunk = options.extinction
      ? `
        uniform float uDustExtinction;`
      : ''
    const outputChunk = options.extinction
      ? `// Over (One, OneMinusSrcAlpha): цвет премультиплирован прежним весом alpha,
          // вклад света тот же haze·litFrac·alpha; фон умножается на 1 − alphaExt
          float alphaExt = (1.0 - exp(-tau * uDustExtinction)) * gate;
          gl_FragColor = vec4(haze * litFrac * alpha, alphaExt);`
      : 'gl_FragColor = vec4(haze * litFrac, alpha);'

    super({
      defines: {
        ...(lightTint.active && { USE_LIGHT_TINT: '1' }),
        ...(options.lightAtOrigin && { DUST_LIGHT_AT_ORIGIN: '1' }),
        ...(options.clumps && { DUST_CLUMPS: '1' }),
        ...(options.phaseHG && { DUST_PHASE_HG: '1' }),
        ...(options.arcs && { DUST_ARCS: '1' })
      },
      uniforms: {
        ...(options.clumps && { uDustClumpGradients: { value: createDustClumpGradientTexture() } }),
        uDustColor: { value: new Color(0x9b968c) },
        // Цвет света звезды (lightTint) — per-instance объект, не общий модульный Uniform
        uLightColor: { value: new Color(1, 1, 1).copy(lightTint.color) },
        uDustDensity: { value: 0.0 },
        uDustScaleHeight: { value: 1.0 },
        uDustRingInner: { value: 0.0 },
        uDustRingOuter: { value: 1e9 },
        uDustCamRingPos: { value: new Vector3() },
        uDustLightDirRing: { value: new Vector3(1, 0, 0) },
        /** Крутизна гейта по углу обзора (спека: дефолт 2) */
        uDustAnglePower: { value: 2.0 },
        /** Дистанция полного проявления пыли, three-units */
        uDustNearFade: { value: 20.0 },
        /** Бюджет шагов марша */
        uDustMaxSteps: { value: 16 },
        /** Радиус планеты в ring-local three-units (0 — тень выключена) */
        uDustPlanetRadius: { value: 0.0 },
        /** Радиальный профиль пыли из альфы текстуры кольца (см. DustRadialProfile) */
        uDustRadialMap: { value: null },
        /** Множитель профиля (среднее модуляции ≈ 1); 0 — профиль выключен */
        uDustRadialMapScale: { value: 0.0 },
        /** Азимутальный профиль пыли — дуги пояса (см. createDustAngularTexture); читается только под DUST_ARCS */
        uDustAngularMap: { value: null },
        /** Множитель азимутального профиля (среднее модуляции ≈ 1) */
        uDustAngularMapScale: { value: 0.0 },
        // Полосы кольца и слой (см. чанк RingDust): самозатенение марша
        uRingBandMap: { value: null },
        uRingBandEnabled: { value: 0.0 },
        uBandMeanColor: { value: new Vector3(1, 1, 1) },
        uBandTintStrength: { value: 1.0 },
        uLayerHalfThickness: { value: 1.0 },
        uLayerShadowStrength: { value: 0.25 },
        /** Диагностика: 0 выкл, 1 τ, 2 alpha, 3 гейт, 4 теплокарта шагов */
        uDustDebugMode: { value: 0 },
        /** Сила клочьев 0..1 (нейтрально при DUST_CLUMPS выключенном) */
        uDustClumpStrength: { value: 0.0 },
        /** Масштаб шума клочьев, three-units; p/scale ~1e4 — вне алиасинга */
        uDustClumpScale: { value: 1.0 },
        /** Асимметрия фазы HG, [-1, 1) (нейтрально при DUST_PHASE_HG выключенном) */
        uDustPhaseG: { value: 0.55 },
        /** Сила подмеса фазы 0..1; 0 — эффект на яркость выключен */
        uDustPhaseStrength: { value: 0.0 },
        /** Цвет дымки при взгляде на звезду (форвард-пик фазы) */
        uDustColorForward: { value: new Color(0x9b968c) },
        /** Доля τ, идущая в поглощение фона, 0..1; 0 — только добавляет свет (нейтрально без опции extinction) */
        uDustExtinction: { value: 0.0 },
        // Глубина сцены (чанк SceneDepth): привязывает DepthVolumePass перед рендером
        uSceneDepth: { value: null },
        uResolution: { value: new Vector2(1, 1) },
        uLogFarFactor: { value: 1.0 },
        uSceneDepthEnabled: { value: 0.0 }
      },
      vertexShader: /* glsl */ `
        ${ShaderChunk.common}

        varying vec3 vRingPos;

        void main() {
          // Геометрия запечена в ring-local space (см. RingDustVolume)
          vRingPos = position;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: /* glsl */ `
        ${ShaderChunk.common}

        #ifdef USE_LIGHT_TINT
          uniform vec3 uLightColor;
        #endif

        ${ringDustUniforms}
        ${ringDustRaymarchFunctions}

        uniform int uDustMaxSteps;
        uniform int uDustDebugMode;
        ${sceneDepthUniforms}${clumpDeclChunk}${arcsDeclChunk}${phaseDeclChunk}${extinctionDeclChunk}

        // Во фрагментном префиксе three modelViewMatrix не объявлен, но рендерер
        // грузит его по имени в любой стадии. Берём именно его, а не
        // viewMatrix * modelMatrix: он camera-relative и не теряет точность
        // на межпланетных координатах.
        uniform mat4 modelViewMatrix;

        ${sceneDepthFunctions}

        varying vec3 vRingPos;

        // Теплокарта для диагностических режимов: синий → зелёный → красный
        vec3 dustDebugHeat(float x) {
          x = clamp(x, 0.0, 1.0);
          vec3 cold = mix(vec3(0.0, 0.1, 0.9), vec3(0.0, 0.9, 0.2), smoothstep(0.0, 0.5, x));
          return mix(cold, vec3(0.95, 0.15, 0.05), smoothstep(0.5, 1.0, x));
        }

        void main() {
          // Фрагмент прокси задаёт только направление луча
          vec3 rayDir = normalize(vRingPos - uDustCamRingPos);
          float gate = ringDustAngleGate(rayDir);
          if (uDustDebugMode == 0 && gate <= 0.0005) discard;

          // Пыльные интервалы: внешний цилиндр минус дыра кольца
          vec2 outerIv = ringDustCircleInterval(uDustCamRingPos, rayDir, uDustRingOuter);
          float o0 = max(outerIv.x, 0.0);
          float o1 = outerIv.y;
          if (o1 <= o0) discard;
          vec2 innerIv = ringDustCircleInterval(uDustCamRingPos, rayDir, uDustRingInner);
          float h0 = max(innerIv.x, o0);
          float h1 = min(innerIv.y, o1);
          bool hasHole = h1 > h0;
          vec2 segA = hasHole ? vec2(o0, h0) : vec2(o0, o1);
          vec2 segB = hasHole ? vec2(h1, o1) : vec2(0.0, -1.0);

          // Обрезка по вертикальной оболочке |y| <= 12H (за ней плотность пренебрежима)
          float slabHalf = uDustScaleHeight * 12.0;
          if (abs(rayDir.y) > 1e-8) {
            float tA = (-slabHalf - uDustCamRingPos.y) / rayDir.y;
            float tB = ( slabHalf - uDustCamRingPos.y) / rayDir.y;
            float s0 = min(tA, tB);
            float s1 = max(tA, tB);
            segA = vec2(max(segA.x, s0), min(segA.y, s1));
            segB = vec2(max(segB.x, s0), min(segB.y, s1));
          }

          // Обрыв по глубине сцены: пыль за камнем, планетой и плотным текселем
          // кольца в τ не попадает. Луч, упёршийся в поверхность до входа в слой,
          // схлопывает оба интервала и уходит в discard ниже.
          float tScene = sceneDepthRayT(mat3(modelViewMatrix) * rayDir);
          segA.y = min(segA.y, tScene);
          segB.y = min(segB.y, tScene);

          float lenA = max(segA.y - segA.x, 0.0);
          float lenB = max(segB.y - segB.x, 0.0);
          float total = lenA + lenB;
          if (total <= 0.0) discard;

          float steps = float(uDustMaxSteps);
          float dt = total / steps;
          // Interleaved Gradient Noise — пер-пиксельный джиттер против бандинга
          float jitter = fract(52.9829189 * fract(0.06711056 * gl_FragCoord.x + 0.00583715 * gl_FragCoord.y));

          float tau = 0.0;
          float litTau = 0.0; // τ, взвешенный тенью планеты (для цвета, не для alpha)
          #ifdef DUST_LIGHT_AT_ORIGIN
            float sunTau = 0.0; // τ, взвешенный прямым лепестком к звезде в начале координат
          #endif${phaseTauDeclChunk}
          float marched = 0.0;
          // 64 — жёсткий потолок GLSL-цикла (граница обязана быть константой):
          // uDustMaxSteps выше 64 молча обрезается. CPU-зеркало tauMarch потолка
          // не имеет — при сверке держать steps <= 64.
          for (int i = 0; i < 64; i++) {
            if (float(i) >= steps) break;
            float s = (float(i) + jitter) * dt;
            float t = s < lenA ? segA.x + s : segB.x + (s - lenA);
            vec3 p = uDustCamRingPos + rayDir * t;
            float contrib = ringDustDensityAt(p) * ringDustNearRamp(t) * dt;${clumpContribChunk}${arcsContribChunk}${phaseContribChunk}
            tau += contrib;
            // Тень планеты и самозатенение слоя кольца — на каждом шаге
            ${shadowContribChunk}
            #ifdef DUST_LIGHT_AT_ORIGIN
              // Звезда в начале ring-local: направление на неё своё в каждой точке марша
              vec3 toStar = -p / max(length(p), 1e-6);
              sunTau += contrib * pow(max(dot(rayDir, toStar), 0.0), 4.0);
            #endif
            marched = float(i) + 1.0;
            // early-exit: насыщение непрозрачности
            if (1.0 - exp(-tau) > 0.995) break;
          }

          float alpha = (1.0 - exp(-tau)) * gate;
          // Освещённая доля τ: средняя тень планеты, взвешенная плотностью вдоль луча
          float litFrac = tau > 0.0 ? litTau / tau : 1.0;

          if (uDustDebugMode != 0) {
            // Диагностика рисуется непрозрачно, поверх всего содержимого объёма
            vec3 dbg = vec3(0.0);
            if (uDustDebugMode == 1) dbg = dustDebugHeat(1.0 - exp(-tau));
            else if (uDustDebugMode == 2) dbg = dustDebugHeat(alpha);
            else if (uDustDebugMode == 3) dbg = dustDebugHeat(gate);
            else if (uDustDebugMode == 4) dbg = dustDebugHeat(marched / steps);
            gl_FragColor = vec4(dbg, 1.0);
            return;
          }

          if (alpha < 0.003) discard;
          // Аддитивный вклад: премультиплай альфой уже делает блендер
          // (SrcAlpha, One), поэтому цвет отдаём как есть, интенсивность в alpha.
          // Тень планеты затемняет цвет (litFrac), но не непрозрачность (alpha)
          #ifdef DUST_LIGHT_AT_ORIGIN
            vec3 haze = ringDustHazeSun(tau > 0.0 ? sunTau / tau : 0.0);
          #else
            vec3 haze = ringDustHaze(rayDir);
          #endif${phaseHazeOverrideChunk}
          ${outputChunk}
        }
      `,
      side: BackSide,
      transparent: true,
      depthWrite: false,
      depthTest: false,
      // Over премультиплированный: RGB и альфа одними множителями, чтобы
      // альфа-канал HDR-буфера не расходился с цветом (непрозрачный фон остаётся 1)
      ...(options.extinction
        ? {
            blending: CustomBlending,
            blendEquation: AddEquation,
            blendEquationAlpha: AddEquation,
            blendSrc: OneFactor,
            blendDst: OneMinusSrcAlphaFactor,
            blendSrcAlpha: OneFactor,
            blendDstAlpha: OneMinusSrcAlphaFactor
          }
        : { blending: AdditiveBlending })
    })
    this.clumpGradients = this.uniforms.uDustClumpGradients?.value
  }

  public override copy(source: this): this {
    if (source === this) return this
    this.clumpGradients?.dispose()
    super.copy(source)
    // ShaderMaterial.copy clones texture uniforms; own that clone, not source's.
    this.clumpGradients = this.uniforms.uDustClumpGradients?.value
    return this
  }

  public override dispose(): void {
    this.clumpGradients?.dispose()
    // Like ShaderMaterial itself, the texture can be uploaded again after
    // disposal. Retain ownership so a subsequent dispose still releases it.
    super.dispose()
  }
}

export { RingDustRaymarchMaterial }
export type { RingDustRaymarchOptions }

import { Color, Mesh, SphereGeometry, type Texture, type Vector2, Vector3 } from 'three'
import { RingDustRaymarchMaterial } from './RingDustRaymarchMaterial'
import { createDustAngularTexture, createDustRadialTexture } from './DustRadialProfile'
import type { DepthVolumeRegistry } from '@/core/services/DepthVolumeRegistry'
import type { Disposable } from '@/core/lifecycle/Disposable'
import { DEPTH_VOLUME_LAYER, type DepthVolume } from '@/core/graphic/passes/DepthVolume'
import type { Actor } from '@/core/models/Actor'

/**
 * Множитель вертикальной оболочки в единицах H — константа обрезки марша в
 * шейдере (|y| <= 12H, за ней плотность пренебрежима). С прокси-сферой на
 * геометрию больше не влияет, но остаётся единым источником этого числа для
 * шейдера и тестов точности (RingDustTauAccuracy.spec.ts).
 */
const DUST_SLAB_FACTOR = 12

/** Радиальный запас охватывающей сферы относительно внешнего радиуса кольца */
const RADIAL_PADDING = 1.05

interface RingDustVolumeConfig {
  /** Внутренний радиус кольца камней, three-units */
  innerRadius: number
  /** Внешний радиус кольца камней, three-units */
  outerRadius: number
  /** Масштабная полутолщина пылевого слоя H, three-units */
  dustScaleHeight: number
  /** Оптическая плотность в средней плоскости, tau на three-unit */
  dustDensity: number
  /** Цвет дымки */
  dustColor: Color
  /** Крутизна гейта по углу обзора */
  anglePower: number
  /** Дистанция полного проявления пыли, three-units */
  nearFade: number
  /** Бюджет шагов марша */
  maxSteps: number
  /** Радиус планеты для тени, three-units (0 — тень выключена) */
  planetRadius: number
  /** Актор кольца — вход подписки на цвет света звезды (lightTint); undefined — тинт выключен. */
  model?: Actor
  /** Светило в начале ring-local (пояс): прямой лепесток по точке марша, см. RingDustRaymarchOptions */
  lightAtOrigin?: boolean
  /** Сила клочьев 0..1; 0 или не задано — модуляция выключена (дефайн не ставится) */
  clumpStrength?: number
  /** Масштаб шума клочьев, three-units (см. precision-заметку в RingDustRaymarchMaterial) */
  clumpScale?: number
  /** Асимметрия фазы HG, [-1, 1); по умолчанию 0.55 */
  phaseG?: number
  /** Сила подмеса фазы 0..1; 0 или не задано — эффект выключен (дефайн не ставится) */
  phaseStrength?: number
  /** Цвет дымки на форвард-пике (взгляд на звезду); по умолчанию = dustColor */
  colorForward?: Color
  /** Доля τ, гасящая фон за дымкой, 0..1; 0 или не задано — аддитивная дымка без поглощения (опция не ставится) */
  extinction?: number
  /**
   * Радиальный профиль плотности пыли (бины ≥ 0 по u = (r − inner)/(outer − inner));
   * без него модуляция выключена. Кольцо получает его позже из альфы текстуры.
   */
  radialProfile?: Float32Array
  /**
   * Азимутальный профиль плотности (дуги пояса, buildBeltAngularProfile: бины
   * по долям оборота от atan2(z, x)); без него модуляция по углу выключена
   * (дефайн не ставится). Кольца его не задают.
   */
  angularProfile?: Float32Array
  /**
   * Реестр пасса DepthVolumePass: объём регистрируется при создании и снимается в
   * dispose(). Без реестра объём в графе есть, но не рисуется (пасс о нём не
   * знает) — режим тестов и автономных сцен.
   */
  registry?: DepthVolumeRegistry
}

/**
 * RingDustVolume — прокси-гало пылевой дымки кольца.
 *
 * Прокси — ОХВАТЫВАЮЩАЯ СФЕРА радиуса outerRadius·padding, центрированная в
 * центре кольца; материал рендерит backface'ы, интегрируя дымку вдоль луча
 * камера→направление. Сфера покрывает проекцию кольца из любого ракурса
 * (снаружи — диск сферы, изнутри — весь экран), поэтому гало не ограничено
 * силуэтом прокси, как было с тонкой шайбой. Сфера симметрична — поворот в
 * ring-local не нужен, mesh-local (XZ-плоскость, нормаль Y) совпадает с
 * ring-local space родительской системы.
 *
 * Живёт в графе сцены (матрицы считает основной проход), но рисуется пассом
 * DepthVolumePass: лежит на слое DEPTH_VOLUME_LAYER и числится в реестре пасса.
 */
class RingDustVolume extends Mesh implements DepthVolume, Disposable {
  public readonly dustMaterial: RingDustRaymarchMaterial
  /** Радиус описанной сферы прокси (см. DepthVolume.boundingRadius) */
  public readonly boundingRadius: number

  private registry: DepthVolumeRegistry | null
  /**
   * Свои DataTexture профилей. Живут только в юниформах материала, а
   * material.dispose() их не трогает — без явного освобождения каждая смена
   * сценария оставляла их на GPU
   */
  private readonly profileTextures: Texture[] = []

  public constructor(config: RingDustVolumeConfig) {
    const geometry = new SphereGeometry(config.outerRadius * RADIAL_PADDING, 32, 16)

    const clumps = (config.clumpStrength ?? 0) > 0
    const phaseHG = (config.phaseStrength ?? 0) > 0
    // Кламп [0, 1]: при k ≤ 1 гашение не превышает добавленный свет, ранний
    // выход по alpha < 0.003 остаётся безопасным
    const extinctionStrength = Math.min(1, Math.max(0, config.extinction ?? 0))
    const extinction = extinctionStrength > 0
    // Текстура дуг строится до материала: вырожденный профиль (null) не ставит дефайн
    const angular = config.angularProfile ? createDustAngularTexture(config.angularProfile) : null
    const material = new RingDustRaymarchMaterial(config.model, {
      lightAtOrigin: config.lightAtOrigin ?? false,
      clumps,
      phaseHG,
      extinction,
      arcs: angular !== null
    })
    super(geometry, material)
    this.boundingRadius = config.outerRadius * RADIAL_PADDING

    this.dustMaterial = material
    this.layers.set(DEPTH_VOLUME_LAYER)

    this.registry = config.registry ?? null
    this.registry?.register(this)
    this.dustMaterial.uniforms.uDustColor.value.copy(config.dustColor)
    this.dustMaterial.uniforms.uDustDensity.value = config.dustDensity
    this.dustMaterial.uniforms.uDustScaleHeight.value = config.dustScaleHeight
    this.dustMaterial.uniforms.uDustRingInner.value = config.innerRadius
    this.dustMaterial.uniforms.uDustRingOuter.value = config.outerRadius
    this.dustMaterial.uniforms.uDustAnglePower.value = config.anglePower
    this.dustMaterial.uniforms.uDustNearFade.value = config.nearFade
    this.dustMaterial.uniforms.uDustMaxSteps.value = config.maxSteps
    this.dustMaterial.uniforms.uDustPlanetRadius.value = config.planetRadius
    this.dustMaterial.uniforms.uDustClumpStrength.value = config.clumpStrength ?? 0
    this.dustMaterial.uniforms.uDustClumpScale.value = config.clumpScale ?? 1
    this.dustMaterial.uniforms.uDustPhaseG.value = config.phaseG ?? 0.55
    this.dustMaterial.uniforms.uDustPhaseStrength.value = config.phaseStrength ?? 0
    this.dustMaterial.uniforms.uDustColorForward.value.copy(config.colorForward ?? config.dustColor)
    this.dustMaterial.uniforms.uDustExtinction.value = extinctionStrength

    const radial = config.radialProfile ? createDustRadialTexture(config.radialProfile) : null
    if (radial) {
      this.dustMaterial.uniforms.uDustRadialMap.value = radial.texture
      this.dustMaterial.uniforms.uDustRadialMapScale.value = radial.scale
      this.profileTextures.push(radial.texture)
    }
    if (angular) {
      this.dustMaterial.uniforms.uDustAngularMap.value = angular.texture
      this.dustMaterial.uniforms.uDustAngularMapScale.value = angular.scale
      this.profileTextures.push(angular.texture)
    }

    // Порядок относительно 2D-текстуры кольца и камней задаёт не renderOrder,
    // а сам пасс: гало рисуется после всей сцены, поверх готового кадра

    // Прокси окружает камеру при полёте внутри кольца — bounding-сферой не отсечь
    this.frustumCulled = false
    this.name = 'RingDustVolume'
  }

  /** Пер-кадровое обновление: камера и направление на звезду в ring-local space */
  public updatePerFrame(camRingPos: Vector3, lightDirRing: Vector3): void {
    this.dustMaterial.uniforms.uDustCamRingPos.value.copy(camRingPos)
    this.dustMaterial.uniforms.uDustLightDirRing.value.copy(lightDirRing)
  }

  /** Привязка глубины сцены перед рендером пассом (контракт DepthVolume) */
  public bindSceneDepth(sceneDepth: Texture, resolution: Vector2, logFarFactor: number): void {
    const u = this.dustMaterial.uniforms
    u.uSceneDepth.value = sceneDepth
    u.uResolution.value.copy(resolution)
    u.uLogFarFactor.value = logFarFactor
    u.uSceneDepthEnabled.value = 1
  }

  public unbindSceneDepth(): void {
    this.dustMaterial.uniforms.uSceneDepthEnabled.value = 0
  }

  /**
   * Снимает объём с реестра пасса и освобождает текстуры профилей.
   * Идемпотентно; геометрию и материал освобождает обход дерева
   */
  public dispose(): void {
    this.registry?.unregister(this)
    this.registry = null

    for (const texture of this.profileTextures) texture.dispose()
    this.profileTextures.length = 0
  }
}

export { RingDustVolume, DUST_SLAB_FACTOR }
export type { RingDustVolumeConfig }

import { DataTexture, FloatType, NearestFilter, RepeatWrapping, RGBAFormat } from 'three'

const PERIOD = 289

/** The same 3D simplex gradients as Noise.ts, with two permutation stages
 * precomputed: texel(x, y) = gradient(permute(permute(y) + x)).
 * This caches a finite gradient set, not samples of the spatial noise field.
 * RGBA32F costs 1,336,336 bytes; retain CPU pixels for context restoration. */
export function createDustClumpGradientTexture(): DataTexture {
  const f = Math.fround
  // Integer intermediates for x <= 577 fit exactly in float32 (< 2^24).
  const permute = (x: number): number => ((34 * x + 1) * x) % PERIOD
  const n = f(1 / 7), nx = f(n * 2), ny = f(f(n * 0.5) - 1)
  const gradients = Array.from({ length: PERIOD }, (_, p) => {
    // Round constants and operations like the original GLSL octahedral gradient
    // construction and Taylor normalization, rather than using unit vectors.
    const j = p - 49 * Math.floor(f(f(p * n) * n))
    const a = Math.floor(f(j * n)), b = Math.floor(j - 7 * a)
    const x = f(f(a * nx) + ny), y = f(f(b * nx) + ny)
    const h = f(f(1 - Math.abs(x)) - Math.abs(y))
    const sh = h <= 0 ? -1 : 0
    const gx = f(x + (Math.floor(x) * 2 + 1) * sh)
    const gy = f(y + (Math.floor(y) * 2 + 1) * sh)
    const lengthSquared = f(f(f(gx * gx) + f(gy * gy)) + f(h * h))
    const norm = f(f(1.79284291400159) - f(f(0.85373472095314) * lengthSquared))
    return [f(gx * norm), f(gy * norm), f(h * norm), 1]
  })
  const pixels = new Float32Array(PERIOD * PERIOD * 4)
  for (let y = 0; y < PERIOD; y++) {
    const py = permute(y)
    for (let x = 0; x < PERIOD; x++) {
      pixels.set(gradients[permute(py + x)], (y * PERIOD + x) * 4)
    }
  }
  const texture = new DataTexture(pixels, PERIOD, PERIOD, RGBAFormat, FloatType)
  texture.name = 'Dust clump gradients'
  texture.minFilter = NearestFilter
  texture.magFilter = NearestFilter
  texture.wrapS = RepeatWrapping
  texture.wrapT = RepeatWrapping
  texture.generateMipmaps = false
  texture.needsUpdate = true
  return texture
}

/** Dust-only version of Noise.ts snoise(vec3). Keep skew, corner ordering,
 * kernel and arithmetic order in sync; the browser probe compares both GLSL
 * paths. Shared terrain/star noise and its CPU mirror remain independent. */
export const dustClumpNoiseFunctions = `
  uniform sampler2D uDustClumpGradients;

  vec4 dustClumpPermute(vec4 x) {
    vec4 p = ((x * 34.0) + 1.0) * x;
    return p - floor(p * (1.0 / 289.0)) * 289.0;
  }

  float dustClumpNoise(vec3 v) {
    const vec2 C = vec2(1.0/6.0, 1.0/3.0);
    vec3 i = floor(v + dot(v, C.yyy));
    vec3 x0 = v - i + dot(i, C.xxx);
    vec3 g = step(x0.yzx, x0.xyz);
    vec3 l = 1.0 - g;
    vec3 i1 = min(g.xyz, l.zxy);
    vec3 i2 = max(g.xyz, l.zxy);
    vec3 x1 = x0 - i1 + 1.0 * C.xxx;
    vec3 x2 = x0 - i2 + 2.0 * C.xxx;
    vec3 x3 = x0 - 1.0 + 3.0 * C.xxx;

    i = mod(i, 289.0);
    vec4 gx = i.x + vec4(0.0, i1.x, i2.x, 1.0);
    vec4 gy = dustClumpPermute(i.z + vec4(0.0, i1.z, i2.z, 1.0))
      + i.y + vec4(0.0, i1.y, i2.y, 1.0);
    // Nearest/repeat fetches the exact gradient, wrapping both permutations'
    // period. Explicit LOD avoids derivative work inside the raymarch loop.
    vec3 p0 = textureLod(uDustClumpGradients, (vec2(gx.x, gy.x) + 0.5) / 289.0, 0.0).xyz;
    vec3 p1 = textureLod(uDustClumpGradients, (vec2(gx.y, gy.y) + 0.5) / 289.0, 0.0).xyz;
    vec3 p2 = textureLod(uDustClumpGradients, (vec2(gx.z, gy.z) + 0.5) / 289.0, 0.0).xyz;
    vec3 p3 = textureLod(uDustClumpGradients, (vec2(gx.w, gy.w) + 0.5) / 289.0, 0.0).xyz;

    vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
    m = m * m;
    return 42.0 * dot(m*m, vec4(dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3)));
  }
`

