    const radius = fromAstronomicalUnits((data.innerRadiusAu + data.outerRadiusAu) / 2)
    let belt = target
    target.traverse((object: any) => { if (object.constructor.name === 'AsteroidBelt') belt = object })
    camera.position.copy(new Vector3(radius, 0, 0).applyMatrix4(belt.matrixWorld))
    camera.lookAt(center)
  } else {
    camera.position.copy(center).add(new Vector3(fromAstronomicalUnits(.15), fromAstronomicalUnits(.02), 0))
    camera.lookAt(center)
  }
  c.get(Tokens.CameraCollision).reset()
  return { actorId, kind, center: center.toArray(), requestedPosition: camera.position.toArray(), name: target.model.getAttribute('name') }
}

export async function profile(frames = 60, mode = 'passes', orbit = false) {
  const c = runtime(), engine: any = c.get(Tokens.Engine), renderer = c.get(Tokens.Renderer)
  const camera = c.get(Tokens.Camera), origin = camera.position.clone(), orientation = camera.quaternion.clone()
  const pp: any = c.get(Tokens.Postprocessing), gl = renderer.getContext() as WebGL2RenderingContext
  const timers = new Map<string, GpuTimer>(), cpu: Record<string, number[]> = {}, gpu: Record<string, number[]> = {}
  const restore: (() => void)[] = [], intervals: number[] = [], timeline: any[] = [], counts: any[] = []
  const draws: Record<string, any> = {}
  let active = true, frame = 0, previous = 0, failure: unknown
  const timer = (key: string) => {
    if (!timers.has(key)) { timers.set(key, new GpuTimer(gl)); gpu[key] = [] }
    return timers.get(key)!
  }
  const wrap = (obj: any, key: string, name: string | ((args: any[]) => string), gpuEnabled = false) => {
    const original = obj[key]
    obj[key] = function (...args: any[]) {
      if (!active) return original.apply(this, args)
      const n = typeof name === 'function' ? name(args) : name
      const start = performance.now()
      let result: unknown
      if (gpuEnabled) timer(n).measure(() => { result = original.apply(this, args) })
      else result = original.apply(this, args)
      ;(cpu[n] ??= []).push(performance.now() - start)
      return result
    }
    restore.push(() => { obj[key] = original })
  }
  try {
    new GpuTimer(gl).dispose()
    for (const [i, p] of pp.composer.passes.entries()) {
      wrap(p, 'render', `${i}:${p.name}`, mode === 'passes')
      if (p.name === 'DepthVolumePass' && mode === 'volumes') {
        wrap(p.scaled, 'render', args => 'volume:' + label(args[3]), true)
      }
    }
    if (mode === 'draws') {
      let mainPass = false
      const pass = pp.composer.passes.find((p: any) => p.name === 'RenderPass')
      const renderPass = pass.render
      pass.render = function (...args: any[]) {
        mainPass = true
        try { return renderPass.apply(this, args) } finally { mainPass = false }
      }
      restore.push(() => { pass.render = renderPass })
      const renderDirect = renderer.renderBufferDirect
      renderer.renderBufferDirect = function (...args: any[]) {
        if (!active || !mainPass) return renderDirect.apply(this, args)
        const [, , geometry, material, object] = args
        const key = `${label(object)}#${object.id}`
        draws[key] = { material: material.name || material.type, defines: material.defines,
          count: object.count ?? 1, indices: geometry.index?.count, vertices: geometry.attributes.position?.count,
          drawRange: geometry.drawRange, transparent: material.transparent, side: material.side }
        let result: any
        timer(key).measure(() => { result = renderDirect.apply(this, args) })
        return result
      }
      restore.push(() => { renderer.renderBufferDirect = renderDirect })
    }
    if (mode === 'volumeDraws') {
      const render = renderer.render
      renderer.render = function (object: any, view: any) {
        if (!active || typeof object.bindSceneDepth !== 'function') return render.call(this, object, view)
        const u = object.material?.uniforms
        const phase = u?.uLowResolutionEnabled?.value > 0 ? 'reconstruct' : 'march'
        const key = `${label(object)}:${phase}`
