import { Vector3 } from 'three'
import { AsteroidImpostorLibrary } from '/src/core/renderables/DetailedRingStreamingSystem/impostors/AsteroidImpostorLibrary'
import { fromAstronomicalUnits, toThreeJSUnits } from '/src/core/helpers/scaling'

const runtime = () => getInitializedSimulationRuntime()!.container
export const preparations: { ms: number; frames: number; jobs: number }[] = []
export function installEarlyDensity() {
  const original = AsteroidImpostorLibrary.prototype.prepareInitial
  AsteroidImpostorLibrary.prototype.prepareInitial = async function () {
    await original.call(this)
    const queue = runtime().get(Tokens.NebulaBakeQueue), started = performance.now(), jobs = queue.pendingCount
    let frames = 0
    while (queue.pendingCount) {
      queue.pumpFrame(); frames++
      await new Promise(resolve => setTimeout(resolve, 0))
      if (performance.now() - started > 60000) throw new Error('Initial density preparation timed out')
    }
    preparations.push({ ms: performance.now() - started, frames, jobs })
  }
}
const summarize = (xs: number[]) => {
  const s = xs.slice().sort((a, b) => a - b)
  return { count: s.length, p50: s[Math.ceil(s.length * .5) - 1], p95: s[Math.ceil(s.length * .95) - 1], max: s.at(-1) }
}
const label = (o: any) => {
  const path = []
  for (let p = o; p; p = p.parent) path.push(`${p.name || p.constructor.name}${p.model ? ':' + p.model.getAttribute('id') : ''}`)
  return path.reverse().join('/')
}
export function state() {
  const c = runtime(), queue = c.get(Tokens.NebulaBakeQueue)
  const belts: unknown[] = [], streamers: unknown[] = []
  c.get(Tokens.Scene).traverse((object: any) => {
    if (object.constructor.name === 'AsteroidBelt') belts.push({ label: label(object), lod: object.lodState, streamer: object.streamer !== null, visible: object.streamer?.visible })
    if (object.constructor.name === 'AsteroidRingSystem') streamers.push({ label: label(object), info: object.getDebugInfo() })
  })
  return { ...snapshot(), pending: queue.pendingCount, allocated: queue.allocatedBytes,
    belts, streamers,
    camera: c.get(Tokens.Camera).position.toArray(), orientation: c.get(Tokens.Camera).quaternion.toArray(), volumes: c.get(Tokens.DepthVolumeRegistry).volumes().map((v: any) => ({
      id: v.id, label: label(v), visible: v.visible, position: v.getWorldPosition(new Vector3()).toArray(),
      scale: v.getWorldScale(new Vector3()).toArray(), resolution: v.resolutionScale,
      defines: v.material?.defines, ready: v.material?.uniforms?.uDensityReady?.value,
      lod: v.material?.uniforms?.uLodBlend?.value
    })) }
}

export function setView(actorId: number, kind: 'planet' | 'belt' | 'cloud') {
  const c = runtime(), scene = c.get(Tokens.Scene), camera = c.get(Tokens.Camera)
  let target: any
  scene.traverse((object: any) => {
    if (!target && object.model?.getAttribute('id') === actorId) target = object
  })
  if (!target) throw new Error(`Actor ${actorId} is absent`)
  const center = target.getWorldPosition(new Vector3())
  c.get(Tokens.CameraController).stopFollowing()
  if (kind === 'planet') {
    const radius = toThreeJSUnits(target.model.physicalObject.getAttribute('radius'))
    camera.position.copy(center).add(new Vector3(1, .6, 1).normalize().multiplyScalar(radius * 3))
    camera.lookAt(center)
  } else if (kind === 'belt') {
    const data = target.model.renderingObject.getAttribute('data')
    const radius = fromAstronomicalUnits((data.innerRadiusAu + data.outerRadiusAu) / 2)
    let belt = target
    target.traverse((object: any) => { if (object.constructor.name === 'AsteroidBelt') belt = object })
    camera.position.copy(new Vector3(radius, 0, 0).applyMatrix4(belt.matrixWorld))
    camera.lookAt(center)
  } else {
    camera.position.copy(center).add(new Vector3(fromAstronomicalUnits(.15), fromAstronomicalUnits(.02), 0))
    camera.lookAt(center)
  }
  c.get(Tokens.CameraCollision).reset()
  return { actorId, kind, center: center.toArray(), requestedPosition: camera.position.toArray(), name: target.model.getAttribute('name') }
}

export async function profile(frames = 60, mode = 'passes', orbit = false) {
  const c = runtime(), engine: any = c.get(Tokens.Engine), renderer = c.get(Tokens.Renderer)
  const camera = c.get(Tokens.Camera), origin = camera.position.clone(), orientation = camera.quaternion.clone()
  const pp: any = c.get(Tokens.Postprocessing), gl = renderer.getContext() as WebGL2RenderingContext
  const timers = new Map<string, GpuTimer>(), cpu: Record<string, number[]> = {}, gpu: Record<string, number[]> = {}
