                // в десятки тысяч units аргумент шума порядка сотни. Масштабы
                // ниже ~100 units начнут алиасить
                vec3 clumpP = p / uDustClumpScale;
                float clumpNoise = dustClumpNoise(clumpP) + 0.5 * dustClumpNoise(clumpP * 2.0);
