// Throwaway one-factor diagnosis. No production changes.
export function candidateSources(source: string, uniforms: any): [string, string][] {
  const replace = (text: string, before: string, after: string) => {
    if (!text.includes(before)) throw new Error(`Missing shader marker: ${before}`)
    return text.replaceAll(before, after)
  }
  let fetch = source
  for (const component of ['x', 'y', 'z', 'w']) {
    fetch = replace(fetch,
      `textureLod(uDustClumpGradients, (vec2(gx.${component}, gy.${component}) + 0.5) / 289.0, 0.0)`,
      `texelFetch(uDustClumpGradients, ivec2(mod(vec2(gx.${component}, gy.${component}), 289.0)), 0)`)
  }
  let shadows = source
  if (uniforms.uDustPlanetRadius.value !== 0 || uniforms.uRingBandEnabled.value !== 0) throw new Error('Shadow specialization requires disabled shadows')
  shadows = replace(shadows, 'if (uDustPlanetRadius <= 0.0)', 'if (true)')
  shadows = replace(shadows, 'if (uRingBandEnabled < 0.5)', 'if (true)')
  const noClumps = replace(source, 'if (clumpGain > 0.001)', 'if (false)')
  const flatPhase = replace(source, 'phaseTau += contrib * ringDustPhaseHG(cosTheta);', 'phaseTau += contrib;')
  const noArcs = replace(source, 'contrib *= texture2D(uDustAngularMap, vec2(atan(p.z, p.x) / PI2, 0.5)).r * uDustAngularMapScale;', 'contrib *= 1.0;')
  return [['noClumpsDiagnostic', noClumps], ['flatPhaseDiagnostic', flatPhase], ['noArcsDiagnostic', noArcs], ['constantDisabledShadows', shadows], ['integerGradientFetch', fetch]]
}

// Isolate the disabled-shadow overhead before selecting an implementation.
export function candidateSources(source: string, uniforms: any): [string, string][] {
  const marker = 'litTau += contrib * ringDustPlanetShadow(p) * ringLayerShadow(p);'
  if (!source.includes(marker) || uniforms.uDustPlanetRadius.value !== 0 || uniforms.uRingBandEnabled.value !== 0) throw new Error('Shadow probe precondition')
  return [
    ['noShadowAccumulation', source.replace(marker, 'litTau += contrib;')],
    ['skipOnlyPlanet', source.replace('if (uDustPlanetRadius <= 0.0)', 'if (true)')],
    ['skipOnlyLayer', source.replace('if (uRingBandEnabled < 0.5)', 'if (true)')],
    ['combinedUniformGuard', source.replace(marker, 'if (uDustPlanetRadius > 0.0 || uRingBandEnabled >= 0.5) { ' + marker + ' } else { litTau += contrib; }')],
    ['earlyLayerGuard', source.replace('float ringLayerShadow(vec3 p) {', 'float ringLayerShadow(vec3 p) { if (uRingBandEnabled < 0.5 || uLayerShadowStrength <= 0.0) return 1.0;')]
  ]
}

