import { Color, DataUtils, FloatType, HalfFloatType, Mesh, NoBlending, OrthographicCamera, PlaneGeometry, ShaderMaterial, UniformsUtils, Vector3, WebGLRenderTarget } from 'three'
import { getInitializedSimulationRuntime } from '/src/ui/runtime/simulationRuntime'
import { Tokens } from '/src/core/providers/tokens'
import { GpuTimer } from '/tests/browser/gpuTimer'
import { RingDustRaymarchMaterial as Baseline } from './dust-work-baseline-material-2026-10-23'
import { state } from './profile.browser'
const stats = (v: number[]) => { const s = v.slice().sort((a, b) => a-b); return { count: v.length, p50: s[Math.ceil(v.length*.5)-1], p95: s[Math.ceil(v.length*.95)-1], max: s.at(-1) } }
const owner = (o: any, id: number) => { for (; o; o = o.parent) if (o.model?.getAttribute('id') === id) return true; return false }
export async function confirm(actorId: number, translated = false) {
  const c = getInitializedSimulationRuntime()!.container, engine: any = c.get(Tokens.Engine), renderer = c.get(Tokens.Renderer)
  const liveCamera = c.get(Tokens.Camera), position = liveCamera.position.clone(), orientation = liveCamera.quaternion.clone()
  const volume: any = c.get(Tokens.DepthVolumeRegistry).volumes().find(v => owner(v, actorId) && v.material.uniforms.uDustMaxSteps)
  if (!volume) throw new Error('Dust missing')
  engine.stop()
  if (translated) { liveCamera.position.add(new Vector3(1, 0, 0).applyQuaternion(orientation)); liveCamera.rotateY(Math.PI/2); liveCamera.updateMatrixWorld(true) }
  const savedTarget = renderer.getRenderTarget(), savedAuto = renderer.autoClear, savedColor = renderer.getClearColor(new Color()), savedAlpha = renderer.getClearAlpha(), originalRender = renderer.render
  const targets: WebGLRenderTarget[] = [], materials: ShaderMaterial[] = []
  const baselineOwner = new Baseline(undefined, { clumps: true, extinction: true, arcs: true, phaseHG: true, lightAtOrigin: true })
  const blitMaterial = new ShaderMaterial({ uniforms: { map: { value: null } }, depthTest: false, depthWrite: false, blending: NoBlending,
    vertexShader: 'void main(){gl_Position=vec4(position.xy,0.0,1.0);}',
    fragmentShader: 'uniform sampler2D map; void main(){gl_FragColor=texelFetch(map,ivec2(gl_FragCoord.xy),0);}' })
  const blit = new Mesh(new PlaneGeometry(2,2), blitMaterial), blitCamera = new OrthographicCamera()
  let uniforms: any, view: any, mesh: Mesh, background: any, frozenDepth: WebGLRenderTarget, width=0, height=0, outputType: any, outputSamples=0
  const copy = (source: any) => {
    const target = new WebGLRenderTarget(source.image.width, source.image.height, { type: FloatType, depthBuffer: false, minFilter: source.minFilter, magFilter: source.magFilter }); targets.push(target)
    const previous = renderer.getRenderTarget(); renderer.setRenderTarget(target); blitMaterial.uniforms.map.value = source
    originalRender.call(renderer, blit, blitCamera); renderer.setRenderTarget(previous); return target
  }
  const read = (t: WebGLRenderTarget) => {
    const raw = t.texture.type === HalfFloatType ? new Uint16Array(t.width*t.height*4) : new Float32Array(t.width*t.height*4)
    renderer.readRenderTargetPixels(t,0,0,t.width,t.height,raw)
    const pixels = raw instanceof Uint16Array ? Float32Array.from(raw, DataUtils.fromHalfFloat) : raw
    if (pixels.some(v=>!Number.isFinite(v))) throw new Error('Nonfinite HDR')
    return pixels
  }
  try {
    renderer.render = function(object: any, camera: any) {
      if (object === volume && !uniforms) {
        const out = renderer.getRenderTarget(); if (!out) throw new Error('Expected compositor output')
        uniforms = {}; for (const [name,u] of Object.entries(object.material.uniforms) as any) uniforms[name] = u.value?.isTexture ? { value: u.value } : UniformsUtils.clone({u}).u
        frozenDepth = copy(uniforms.uSceneDepth.value); uniforms.uSceneDepth.value = frozenDepth.texture
        background = copy(out.texture).texture; width = out.width; height = out.height; outputType = out.texture.type; outputSamples = out.samples
        view = camera.clone(); mesh = new Mesh(object.geometry, blitMaterial); mesh.layers.mask = object.layers.mask; mesh.matrixAutoUpdate = false
        mesh.matrix.copy(object.matrixWorld); mesh.updateMatrixWorld(true); mesh.frustumCulled = false
      }
      return originalRender.call(this, object, camera)
    }
    engine.renderFrame(); renderer.render = originalRender; renderer.autoClear = false
    if (!uniforms || outputSamples !== 8 || uniforms.uDustPlanetRadius.value !== 0 || uniforms.uRingBandEnabled.value !== 0) throw new Error('Production preconditions missing')
    const snapshot = state(), output = new WebGLRenderTarget(width,height,{type:outputType,depthBuffer:true,samples:outputSamples}); targets.push(output)
    const make = (fragmentShader: string) => {
      const a = volume.material
      const m = new ShaderMaterial({ uniforms, defines:{...a.defines}, vertexShader:a.vertexShader, fragmentShader, side:a.side, transparent:a.transparent, depthTest:a.depthTest, depthWrite:a.depthWrite,
        blending:a.blending, blendSrc:a.blendSrc, blendDst:a.blendDst, blendEquation:a.blendEquation, blendSrcAlpha:a.blendSrcAlpha, blendDstAlpha:a.blendDstAlpha, blendEquationAlpha:a.blendEquationAlpha })
      materials.push(m); return m
    }
    const baseline = make(baselineOwner.fragmentShader), optimized = make(volume.material.fragmentShader)
    const reset = () => { renderer.setRenderTarget(output); blitMaterial.uniforms.map.value=background; renderer.render(blit,blitCamera) }
    const draw = (candidate: boolean) => { mesh.material=candidate?optimized:baseline; renderer.render(mesh,view) }
    const depthBefore=read(frozenDepth)
    reset(); draw(false); const reference=read(output)
    reset(); draw(true); const actual=read(output)
    const rb=new Uint32Array(reference.buffer), ab=new Uint32Array(actual.buffer)
    let differentBits=0,maxError=0,signal=0
    for(let i=0;i<rb.length;i++){if(rb[i]!==ab[i]) differentBits++;maxError=Math.max(maxError,Math.abs(reference[i]-actual[i]));signal+=Math.abs(reference[i])}
    if(differentBits||signal===0)throw new Error(`HDR mismatch ${differentBits}/${maxError}`)
    const before={textures:renderer.info.memory.textures,programs:renderer.info.programs!.length}
    const gl=renderer.getContext() as WebGL2RenderingContext,timers={baseline:new GpuTimer(gl),optimized:new GpuTimer(gl)},samples={baseline:[] as number[],optimized:[] as number[]}
    try {
      for(let i=0;i<6;i++)for(const candidate of [false,true]){reset();draw(candidate);await new Promise(r=>setTimeout(r,0))}
      for(let i=0;i<32;i++)for(const candidate of(i%2?[true,false]:[false,true])){
        const key=candidate?'optimized':'baseline';reset();timers[key].measure(()=>draw(candidate));await new Promise(r=>setTimeout(r,0))
        for(const k of ['baseline','optimized'] as const)samples[k].push(...timers[k].poll())
      }
      const deadline=performance.now()+30000
      while(timers.baseline.pendingCount||timers.optimized.pendingCount){await new Promise(r=>setTimeout(r,16));for(const k of ['baseline','optimized'] as const)samples[k].push(...timers[k].poll());if(performance.now()>deadline)throw new Error('Timer timeout')}
      if(samples.baseline.length!==32||samples.optimized.length!==32)throw new Error('Incomplete pairs')
    }finally{timers.baseline.dispose();timers.optimized.dispose()}
    reset();draw(false);const repeat=read(output),depthAfter=read(frozenDepth)
    if(repeat.some((v,i)=>v!==reference[i])||depthAfter.some((v,i)=>v!==depthBefore[i]))throw new Error('Frozen inputs drifted')
    const after={textures:renderer.info.memory.textures,programs:renderer.info.programs!.length}
    if(JSON.stringify(before)!==JSON.stringify(after)||gl.getError())throw new Error('GPU resource/error regression')
    const values:any={};for(const [name,u]of Object.entries(uniforms)as any)values[name]=u.value?.isTexture?{texture:true,width:u.value.image.width,height:u.value.image.height}:u.value?.toArray?u.value.toArray():u.value
    const result={translated,snapshot,resolution:[width,height],outputType,outputSamples,uniforms:values,image:{differentBits,maxError,baselineRepeatIdentical:true,sceneDepthIdentical:true},resources:{before,after},summary:{baseline:stats(samples.baseline),optimized:stats(samples.optimized)},samples}
    console.info('DUST_CONFIRM',actorId,translated,JSON.stringify({image:result.image,summary:result.summary}));return result
  }finally{
    renderer.render=originalRender;renderer.setRenderTarget(savedTarget);renderer.setClearColor(savedColor,savedAlpha);renderer.autoClear=savedAuto
    baselineOwner.dispose();materials.forEach(m=>m.dispose());targets.forEach(t=>t.dispose());blit.geometry.dispose();blitMaterial.dispose()
    liveCamera.position.copy(position);liveCamera.quaternion.copy(orientation);engine.start()
  }
}

