      const attachments = Object.fromEntries((result.attachments || []).filter(a => a.body && a.contentType === 'application/json').map(a => [a.name, JSON.parse(Buffer.from(a.body, 'base64').toString())]))
      const diagnostic = attachments['browser-diagnostics'], focused = spec.title === 'dust shadow fast path'
      rows.push({ title: spec.title, status: result.status, durationMs: result.duration, retry: result.retry, errors: result.errors,
        environment: focused ? attachments['webgl-environment'] : undefined, probe: focused ? attachments['probe-result'] : attachments['probe-result']?.status,
        diagnostics: diagnostic ? { pageErrors: diagnostic.pageErrors, failedRequests: diagnostic.failedRequests, warnings: diagnostic.warningClassifications, errors: diagnostic.console.filter(e => e.type === 'error') } : undefined })
    }
  }
  report.suites.forEach(walk)
  return { stats: report.stats, errors: report.errors, rows }
}
function timings(samples, summary) {
  const sorted = samples.slice().sort((a,b)=>a-b), n=sorted.length
  if(n!==32 || summary.count!==n || sorted.some(v=>!Number.isFinite(v)||v<=0) || sorted[15]!==summary.p50 || sorted[30]!==summary.p95 || sorted[31]!==summary.max) throw new Error('Invalid timing batch')
}
