  for(const run of [report.diagnosis.components,report.diagnosis.shadows])for(const row of run.rows)for(const variant of row.rows)timings(variant.samples,variant.summary)
  if(report.production.rows.length!==2)throw new Error('Missing scene')
  for(const scene of report.production.rows){
    if(scene.frozen.length!==2)throw new Error('Missing view')
    for(const row of scene.frozen){
      for(const key of ['baseline','optimized'])timings(row.samples[key],row.summary[key])
      if(row.image.differentBits||row.image.maxError||!row.image.baselineRepeatIdentical||!row.image.sceneDepthIdentical||row.outputSamples!==8||JSON.stringify(row.resources.before)!==JSON.stringify(row.resources.after))throw new Error('Cloud parity/state regression')
      if(row.summary.optimized.p50>=row.summary.baseline.p50)throw new Error('No measured improvement')
