    for(const c of result.results) { const skip=c.depthMode==='occluded'||c.clumps&&c.radius<=0&&c.band<0.5; if(skip?c.shadowCalls!==0:c.shadowCalls<=0)throw new Error('Shadow calls regression') }
  }
  const full=report.verification.fullBrowser
  if(full.stats.expected!==45||full.stats.unexpected||full.stats.skipped||full.stats.flaky||full.errors.length||full.rows.some(r=>r.status!=='passed'||r.retry||r.errors?.length))throw new Error('Full browser suite incomplete')
  if(report.verification.unit.passed!==5559||report.verification.unit.skipped!==7)throw new Error('Unit summary mismatch')
  if(!report.red.rows.some(r=>r.errors.some(e=>e.message.includes('expected zero calls, received 22816'))))throw new Error('Missing RED')
  console.log(`Verified ${report.provenance.length} source hashes, four paired cloud views, 66 native + 66 software cases, 5559 unit and 45 browser tests`)
