    'src/core/renderables/DetailedRingStreamingSystem/dust/DustClumpNoise.ts','src/core/materials/shaders/lib/chunks/RingDust.ts','src/core/materials/shaders/lib/chunks/SceneDepth.ts',
    'tests/ringDust/shadowFastPath.gpu.ts','tests/ringDust/RingDustClumps.spec.ts','tests/ringDust/__snapshots__/RingDustClumps.spec.ts.snap',
    'tests/browser/gpu.e2e.ts','tests/browser/probe.ts','tests/browser/gpuTimer.ts','tests/browser/scenarioSoak.browser.ts','playwright.config.ts',
