      'dust-work-diagnosis-2026-10-23.browser.ts','dust-work-shadows-2026-10-23.browser.ts','dust-shadows-production-2026-10-23.browser.ts',
      'run-dust-work-profile-2026-10-23.mjs','run-dust-work-diagnosis-2026-10-23.mjs','run-dust-work-shadows-2026-10-23.mjs','run-dust-shadows-production-2026-10-23.mjs','archive-dust-shadows-2026-10-23.mjs'].map(n=>prefix+n)
  ])sourceSnapshots[path]=await source(path,false)
  const finalReview=await source(prefix+'dust-shadows-final-review-2026-10-23.json')
  const report={schemaVersion:1,title:'Clumpy dust: skip disabled shadows',recordedAt:new Date().toISOString(),baselineCommit:'cc4bddbc5fc0cd00bbeb7fb0505c00b6b85eabdf',
    diagnosis,red,regression,production,verification:{unit,firstUnitAttempt,fullBrowser,logs},sourceSnapshots,provenance,finalReview,
